import re, ast
for log in ['/workspace/logs/stage_a.log','/workspace/logs/stage_b.log']:
 print('=====',log)
 pat=re.compile(r"model\.py:\d+ - (?:([A-Za-z_][A-Za-z0-9_]*)-)?step (\d+): (\{.*\})\s*$")
 for line in open(log,errors='replace'):
  m=pat.search(line.strip())
